 const bases=this.platforms.filter(p=>p.y>=660);this.fighters.forEach((f,i)=>{const base=bases[i%bases.length];f.x=base.x+base.w*(.25+.5*Math.floor(i/bases.length)/Math.max(1,Math.ceil(5/bases.length)-1));f.y=base.y;});
