 starAttack(f,angle){if(!this.active(f)||f.starTime<=0||f.flowerShot>0)return false;f.flowerShot=.3;f.charge=.25;f.face=Math.cos(angle)>=0?1:-1;this.effect(f.x+f.face*35*f.size,f.y-30*f.size,'#ffe45b',15);for(const e of this.fighters)if(e!==f&&this.active(e)&&!this.allied(f,e)&&Math.hypot(e.x-f.x,e.y-f.y)<110*f.size){const a=Math.atan2(e.y-f.y,e.x-f.x),delta=Math.atan2(Math.sin(a-angle),Math.cos(a-angle));if(Math.abs(delta)<1.2)this.hit(e,32,f.face*350,-180,f.id);}return true;}
