 fireball(f,angle){if(!this.active(f)||!f.fireFlower||f.flowerShots<=0||f.flowerShot>0||(f.type===5&&f.scared>0))return false;f.flowerShot=.32;f.flowerShots--;if(f.flowerShots===0)f.fireFlower=false;if(f.type===11){this.punch(f,angle,18);this.effect(f.x+f.face*40,f.y-30,'#ff9a49',12);return true;}f.aim=angle;f.face=Math.cos(angle)>=0?1:-1;this.bullets.push({x:f.x+Math.cos(angle)*27*f.size,y:f.y-30*f.size+Math.sin(angle)*27*f.size,vx:Math.cos(angle)*580,vy:Math.sin(angle)*580,life:2,owner:f.id,power:3,color:'#ff8b42',fireball:true,mini:true,bounces:0});this.effect(f.x,f.y-30,'#ffb84d',4);return true;}
 get podium(){if(!this.over||this.winnerId===null)return null;const winner=this.fighters.find(f=>f.id===this.winnerId);const loser=this.fighters.find(f=>f.id===this.lastDefeated&&f!==winner)||this.fighters.find(f=>f!==winner&&!f.alive)||this.fighters.find(f=>f!==winner);return {winnerType:winner.baseType,loserType:loser.baseType};}
