 effect(x,y,color,n=14){for(let i=0;i<n;i++){let a=this.random()*Math.PI*2,s=80+this.random()*240;this.fx.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:.35+this.random()*.4,color});}}
 leader(f){const seen=new Set();while(f.commander!==null&&!seen.has(f.id)){seen.add(f.id);const parent=this.fighters.find(e=>e.id===f.commander);if(!parent)break;f=parent;}return f.id;}
