 unicornCharge(f,angle){f.shot=.65;f.charge=.25;f.aim=angle;this.glitterFart(f,18);for(const e of this.fighters)if(e!==f&&this.active(e)&&!this.allied(f,e)&&Math.hypot(e.x-f.x,e.y-f.y)<100){const a=Math.atan2(e.y-f.y,e.x-f.x),delta=Math.atan2(Math.sin(a-angle),Math.cos(a-angle));if(Math.abs(delta)<1.2)this.hit(e,18,Math.sign(e.x-f.x)*220,-100,f.id);}return true;}
