 punch(f,angle,damage=28,rising=false){this.emitSound('punch',f.x,f.y,f.id);f.aim=angle;f.face=Math.cos(angle)>=0?1:-1;f.shot=rising?.5:.4;f.charge=.24;this.effect(f.x+f.face*36*f.size,f.y-32*f.size,'#f4f5ff',10);for(const e of this.fighters){if(e===f||!this.active(e)||this.allied(e,f))continue;const dx=e.x-f.x,dy=e.y-f.y,a=Math.atan2(dy,dx),delta=Math.atan2(Math.sin(a-angle),Math.cos(a-angle));if(Math.hypot(dx,dy)<105*f.size&&Math.abs(delta)<1.25)this.hit(e,damage,f.face*(rising?300:210),rising?-430:-100,f.id);}return true;}
