 hit(f,amount,kx,ky,owner){const attacker=this.fighters.find(e=>e.id===owner);if(!this.active(f)||f.shield>0||f.starTime>0||(attacker&&this.allied(f,attacker)))return;if((f.type===11||f.baseType===11)&&attacker&&(attacker.type===5||attacker.baseType===5)){this.emitSound('sword-hit',f.x,f.y,owner);this.effect(f.x,f.y-30,'#f4f5ff',6);return;}this.emitSound(attacker?.type===5?'sword-hit':'impact',f.x,f.y,owner);const absorbed=Math.min(f.armor,amount);f.armor-=absorbed;if(f.armor===0)f.armorType=null;const healthDamage=amount-absorbed;f.hp-=healthDamage;f.damage+=healthDamage+absorbed*.25;const force=amount>0?1-absorbed/amount*.35:1;f.vx+=kx*force*(1+f.damage/120);f.vy+=ky*force*(1+f.damage/120);f.killer=owner;this.effect(f.x,f.y-25,FIGHTERS[f.type].color,7);this.shake=Math.max(this.shake,5);if(f.hp<=0)this.eliminate(f);}
